using System.ComponentModel.DataAnnotations;
namespace ProductAPI.Models;
public class ProductCategory { public int Id {get;set;} [MaxLength(120)] public string Name {get;set;}=""; public List<Product> Products {get;set;}=new(); }
public class Supplier { public int Id {get;set;} public string Name {get;set;}=""; public string? Email {get;set;} public string? Country {get;set;}="China"; public int LeadTimeDays {get;set;}=30; public string? ContactName {get;set;} public string? Notes {get;set;} }
public class Product { public int Id {get;set;} [MaxLength(80)] public string Sku {get;set;}=""; [MaxLength(200)] public string Name {get;set;}=""; public string? Description {get;set;} public int? CategoryId {get;set;} public ProductCategory? Category {get;set;} public int? SupplierId {get;set;} public Supplier? Supplier {get;set;} public decimal PurchasePrice {get;set;} public decimal RetailPrice {get;set;} public decimal ResellerPrice {get;set;} [MaxLength(3)] public string Currency {get;set;}="SEK"; public int StockQuantity {get;set;} public int ReservedQuantity {get;set;} public int TargetStockQuantity {get;set;}=100; public int ReorderThresholdPercent {get;set;}=20; public bool Active {get;set;}=true; public int ReorderQuantity {get;set;}=0; public uint Version {get;set;} public List<ProductImage> Images {get;set;}=new(); }
public class Reseller { public int Id {get;set;} public string Name {get;set;}=""; public string? Email {get;set;} public bool Active {get;set;}=true; public List<ApiKey> ApiKeys {get;set;}=new(); }
public class ApiKey { public int Id {get;set;} public string Name {get;set;}=""; [MaxLength(20)] public string Prefix {get;set;}=""; [MaxLength(64)] public string Hash {get;set;}=""; public int? ResellerId {get;set;} public Reseller? Reseller {get;set;} public bool IsAdmin {get;set;} public bool Revoked {get;set;} public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; public DateTime ExpiresUtc {get;set;} public DateTime? LastUsedUtc {get;set;} public string Scopes {get;set;}="products:read"; }
public class StockMovement { public long Id {get;set;} public int ProductId {get;set;} public Product Product {get;set;}=null!; public int Delta {get;set;} public string Reason {get;set;}=""; public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; }
public class ResellerOrder { public long Id {get;set;} public int ResellerId {get;set;} public Reseller Reseller {get;set;}=null!; public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; public string Status {get;set;}="Pending"; public List<ResellerOrderItem> Items {get;set;}=new(); }
public class ResellerOrderItem { public long Id {get;set;} public long ResellerOrderId {get;set;} public int ProductId {get;set;} public int Quantity {get;set;} public decimal UnitPrice {get;set;} }
public class PurchaseOrder { public long Id {get;set;} public int SupplierId {get;set;} public Supplier Supplier {get;set;}=null!; public string Status {get;set;}="Draft"; public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; public DateTime? OrderedUtc {get;set;} public DateTime? ReceivedUtc {get;set;} public string? Reference {get;set;} public string? Notes {get;set;} public List<PurchaseOrderItem> Items {get;set;}=new(); }
public class PurchaseOrderItem { public long Id {get;set;} public long PurchaseOrderId {get;set;} public PurchaseOrder PurchaseOrder {get;set;}=null!; public int ProductId {get;set;} public Product Product {get;set;}=null!; public int Quantity {get;set;} public int ReceivedQuantity {get;set;} public decimal UnitCost {get;set;} }
